231	  /* ──────────────────────────────────────────────────────────
232	     LEGACY ALIASES — redirect non-brand tokens to Rust
233	     (Brand Book v1.0 four-color rule: Bone / Onyx / Stone / Rust only)
234	  ────────────────────────────────────────────────────────── */
235	  --color-electric-purple:    var(--color-rust);
236	  --color-electric-purple-10: oklch(58% 0.16 35 / 0.1);
237	  --color-electric-purple-20: oklch(58% 0.16 35 / 0.2);
